mapper.sql:
from mst_item i


    and (i.item_cd like #{q.itemCdLike} escape '\'
        or exists (select 1 from mst_ext_id_map x where x.entity_type = 'ITEM' and x.use_yn = 'Y'
                    and x.internal_id = i.item_id and upper(x.external_id) like #{q.itemCdLike} escape '\'))
    and (i.item_nm ilike #{q.itemNmLike} escape '\' or i.spec ilike #{q.itemNmLike} escape '\')
    and i.item_type = #{q.itemType}
    and i.proc_type = #{q.procType}
    and i.use_yn = #{q.useYn}
